TLM.f("Commune/C10b",{"officium":"Sancta Maria Sabbato a Nativitate usque ad Purificationem: Vultum tuum","rule":["Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 44:13; 44:15; 44:16"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne."}],"Oratio":[{"k":"text","la":"Deus, qui salútis ætérnæ, beátæ Maríæ virginitáte fecúnda, humáno generi præmia præstitísti: tríbue, quǽsumus; ut ipsam pro nobis intercédere sentiámus, per quam merúimus auctórem vitæ suscípere, Dóminum nostrum Jesum Christum, Fílium tuum:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Titum"},{"k":"ref","la":"Tit 3:4-7"},{"k":"text","la":"Caríssime: Appáruit benígnitas et humánitas Salvatóris nostri Dei: non ex opéribus justítiæ, quæ fécimus nos, sed secúndum suam misericórdiam salvos nos fecit, per lavácrum regeneratiónis et renovatiónis Spíritus Sancti, quem effúdit in nos abúnde per Jesum Christum, Salvatórem nostrum: ut, justificáti grátia ipsíus, herédes simus secúndum spem vitæ ætérnæ: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 44:3; 44:2"},{"k":"text","la":"Speciósus forma præ fíliis hóminum: diffúsa est grátia in lábiis tuis."},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi: lingua mea cálamus scribæ velóciter scribéntis. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.","mark":"V"}],"Tractus":[{"k":"text","la":"Speciósus forma præ fíliis hóminum: diffúsa est grátia in lábiis tuis."},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi: lingua mea cálamus scribæ velóciter scribéntis.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 2:15-20"},{"k":"text","la":"In illo témpore: Pastóres loquebántur ad ínvicem: Transeámus usque Béthlehem, et videámus hoc verbum, quod factum est, quod Dóminus osténdit nobis. Et venérunt festinántes, et invenérunt Maríam, et Joseph, et Infántem pósitum in præsépio. Vidéntes autem cognovérunt de verbo, quod dictum erat illis de Púero hoc. Et omnes, qui audiérunt, miráti sunt: et de his, quæ dicta erant a pastóribus ad ipsos. María autem conservábat ómnia verba hæc, cónferens in corde suo. Et revérsi sunt pastores, glorificántes et laudántes Deum in ómnibus, quæ audíerant et víderant, sicut dictum est ad illos."}],"Offertorium":[{"k":"text","la":"Felix namque es, sacra Virgo María, et omni laude digníssima: quia ex te ortus est sol justítiæ, Christus, Deus noster."}],"Secreta":[{"k":"text","la":"Tua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedénte beáta Vírgine Dei Genetríce María, cœléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per eundem"}]},"hr":{"92898c593a318cb8":{"t":"Ps 44, 13 i 15 i 16, Ps 44, 2\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju."},"c79c33bb27747538":{"t":"<i>Pomolimo se</i>.\nBože, koji si plodnim djevičanstvom blažene Marije darovao ljudskom rodu dobra vječnog spasenja, podaj, molimo te, da osjetimo zagovor one po kojoj smo zavrijedili primiti početnika života, Gospodina našega Isusa Krista, Sina tvoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"2, (O BI. Djevici Mariji). Bože, koji si ljudskom rodu po /plodnom djevičanstvu blažene Marije udijelio nagrade vječnoga spasenja, podaj, molimo, da osjetimo zagovor one, po kojoj smo zaslužili primiti početnika života, Gospodina našega Isusa Krista . . .","knRef":"Kniewald 1942, str. 852–853 (snimka 427) (OCR)"},"e0f30f9a6fa2333c":{"t":"Tit 3, 4-7\nČitanje Poslanice bl. Pavla apostola Titu. Predragi: objavila se dobrota i čovjekoljublje Boga našega Spasitelja. On nas je spasio, ali ne po našim pravednim djelima nego po svojem milosrđu, po kupelji preporoda i obnove Duha Svetoga. Njega je na nas obilno izlio po našem Spasitelju Isusu Kristu, da opravdani njegovom milošću budemo po ufanju baštinici vječnog života u našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi, Pavla apostola Titu (3, 4-7). Predragi! Objavila se dobrota i čovjekoljublje Spasitelja našega Boga. On nas je spasio, ali ne po pravednim djelima., što smo ih mi učinili, nego po svomu milosrđu, po kupelji preporoda i obnove Duha Svetoga., koijega je obilno na nas izlio po Božić — ■ danja misa Isusu Kristu Spasitelju našemu, da opravdani njegovom milošću, po ufanju budemo baštinici vječnoga života u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 58–59 (snimka 30) (OCR)"},"e2076f8db40cba8c":{"t":"Ps 44, 3, Ps 44, 2\nNajljepši si od sinova ljudskih, ljupkost ti je razlivena na usnama. Iz mog srca vinula se dobra riječ; svoja djela posvećujem kralju. Jezik je moj poput pera pisara što piše brzo.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nPoslije porođaja ostala si, Djevice, nepovrijeđena; Bogorodice, zagovaraj nas. <i>Aleluja</i>.","kn":"(Ps. 44, 3, 2). Ljepši si od svih sinova ljudskih, razlito je milje na usnama Tvojim. Iz mog srca izvire divna pjesma, ja posvećujem djela svoja Kralju! Jezik je moj kao pero ipisara, što brzo piše. AleluJa, aieluja.","knRef":"Kniewald 1942, str. 670–671 (snimka 336) (OCR)"},"87d338e1955655ec":{"t":"Lk 2, 15-20\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: pozovu pastiri jedan drugoga: »Pođimo u Betlehem da vidimo što se dogodilo, kako nam je objavio Gospodin!« Pođu žurno i nađu Mariju i Josipa i Dijete položeno u jasle. Kad su vidjeli, shvatili su što im je rečeno o tom Djetetu. Svi koji su čuli, divili su se onome što su im kazivali pastiri. Sve je te riječi Marija pamtila razmišljajući u svom srcu. A pastiri se vrate slaveći Boga za sve što su čuli i vidjeli, kako im je bilo rečeno.","kn":"t Slijedi sveto Evanđelje po Luki (2, 15-20). U ono vrijeme rekoše pastiri jedan drugome: Pođimo do Betlehema, da vidimo, što ee dogodilo, kako nam je objavio Gospodin. Pođu žurno i nađu Mariju i Josipa i dijete, gdje leži u jaslama. I kad oni odu, vidješe, i uvjeriše se o tom, što im je bilo rečeno o ovom djetetu. I svi, koji su čuli, divili su se onomu, što su im kazivali pastiri. A Marija je sve ovo pamtila razmišljajući u svom srcu. I pastiri se povratiše slaveći Boga za sve, što su čuli i vidjeli, kako im je bilo kazano.","knRef":"Kniewald 1942, str. 60–61 (snimka 31) (OCR)"},"af6c9a47cafda1e9":{"t":"Sretna si, sveta Djevice Marijo, i svake si hvale dostojna, jer je iz tebe isteklo Sunce pravde, Krist Bog naš."},"b5b1bdcbf7bad4ad":{"t":"Tvojim smilovanjem, Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i sadašnju sreću i mir.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Tvojom milostivošću. Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i' -sadašnju sreću i mir, po' G; n,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"8587796109dd15d5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>u čašćenju</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"4cc414b9b992a40d":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca.","kn":"Blaženokrilo Djevice Marije, koje je nosilo Sina vječnoga Oca,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"f3420e82111d9894":{"t":"<i>Pomolimo se</i>.\nOva Pričest, Gospodine, neka nas očisti od opačina i zagovorom blažene Djevice Bogorodice Marije neka nas učini dionicima nebeskog lijeka.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Ova nas pričest. Gospodine, očistila od krivice, i . zagovorom blažene Djevice i Bogorodice Marije učinila dionicima nebeskoga, lijeka, po G. n.","knRef":"Kniewald 1942, str. 736–737 (snimka 369) (OCR)"}}});
